### 💻 RAII Smart Pointer Implementation (UniquePtr in C++)

**Language / Ecosystem:** `cpp`
**Overview:** Implements an exclusive-ownership smart pointer from scratch with explicit move semantics, deleted copy constructor, and RAII automatic deallocation.

```cpp
#include <iostream>
#include <utility>

template <typename T>
class UniquePtr {
private:
    T* ptr;
public:
    explicit UniquePtr(T* p = nullptr) : ptr(p) {}
    ~UniquePtr() { delete ptr; }

    UniquePtr(const UniquePtr&) = delete;
    UniquePtr& operator=(const UniquePtr&) = delete;

    UniquePtr(UniquePtr&& other) noexcept : ptr(other.ptr) {
        other.ptr = nullptr;
    }

    UniquePtr& operator=(UniquePtr&& other) noexcept {
        if (this != &other) {
            delete ptr;
            ptr = other.ptr;
            other.ptr = nullptr;
        }
        return *this;
    }

    T& operator*() const { return *ptr; }
    T* operator->() const { return ptr; }
    T* get() const { return ptr; }
};

int main() {
    UniquePtr<int> val(new int(100));
    std::cout << "Value: " << *val << std::endl;
    UniquePtr<int> moved = std::move(val);
    std::cout << "Moved: " << *moved << std::endl;
    return 0;
}
```

