### 💻 Quicksort in JavaScript (Average O(n log n))

**Language / Ecosystem:** `javascript`
**Overview:** In-place quicksort algorithm with partitioning.

```javascript
function quicksort(arr, low = 0, high = arr.length - 1) {
  if (low < high) {
    const pivotIndex = partition(arr, low, high);
    quicksort(arr, low, pivotIndex - 1);
    quicksort(arr, pivotIndex + 1, high);
  }
  return arr;
}

function partition(arr, low, high) {
  const pivot = arr[high];
  let i = low - 1;
  for (let j = low; j < high; j++) {
    if (arr[j] <= pivot) {
      i++;
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
  return i + 1;
}

const numbers = [38, 27, 43, 3, 9, 82, 10];
console.log("Sorted:", quicksort(numbers));
```

write a quicksort in c++:
### 💻 Quicksort in CPP (In-Place Lomuto Partition)

**Language / Ecosystem:** `cpp`
**Overview:** Sorts vector using divide-and-conquer quicksort in average O(n log n) time.

```cpp
#include <iostream>
#include <vector>
#include <utility>

int partition(std::vector<int>& arr, int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; ++j) {
        if (arr[j] <= pivot) {
            ++i;
            std::swap(arr[i], arr[j]);
        }
    }
    std::swap(arr[i + 1], arr[high]);
    return i + 1;
}

void quicksort(std::vector<int>& arr, int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

int main() {
    std::vector<int> data = {10, 80, 30, 90, 40, 50, 70};
    quicksort(data, 0, data.size() - 1);
    for (int x : data) std::cout << x << " ";
    std::cout << std::endl;
    return 0;
}
```

