from collections import Counter

def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    return Counter(s.lower()) == Counter(t.lower())

def is_anagram_optimized(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
