    for c1, c2 in zip(s.lower(), t.lower()):
        if 'a' <= c1 <= 'z': counts[ord(c1) - ord('a')] += 1
        if 'a' <= c2 <= 'z': counts[ord(c2) - ord('a')] -= 1
