### 💻 Implement Queue using Two Stacks (Amortized O(1) Operations)

**Language / Ecosystem:** `python`
**Overview:** FIFO queue using two LIFO stacks with amortized constant time push, pop, and peek.

```python
class MyQueue:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def push(self, x: int) -> None:
        self.in_stack.append(x)

    def _shift(self) -> None:
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())

    def pop(self) -> int:
        self._shift()
        if not self.out_stack:
            raise IndexError("Queue is empty")
        return self.out_stack.pop()

    def peek(self) -> int:
        self._shift()
        if not self.out_stack:
            raise IndexError("Queue is empty")
        return self.out_stack[-1]

    def empty(self) -> bool:
        return not self.in_stack and not self.out_stack

q = MyQueue()
q.push(1)
q.push(2)
q.push(3)
print("Peek:", q.peek())
print("Pop:", q.pop())
print("Pop:", q.pop())
print("Empty:", q.empty())
```

