**Language / Ecosystem:** `cpp`
**Overview:** Searches for target in a sorted vector returning index or -1.

```cpp
#include <iostream>
#include <vector>

int binary_search(const std::vector<int>& arr, int target) {
    int left = 0;
    int right = static_cast<int>(arr.size()) - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

int main() {
    std::vector<int> nums = {1, 3, 5, 7, 9, 11, 13, 15};
    int target = 7;
    int idx = binary_search(nums, target);
    std::cout << "Target " << target << " found at index: " << idx << std::endl;
    return 0;
}
```

