**Overview:** A fully functional command-line todo list application with add, complete, delete, list operations and JSON file persistence.

```python
import json
import os

TODO_FILE = "todos.json"

def load_todos():
    if os.path.exists(TODO_FILE):
        with open(TODO_FILE, "r") as f:
            return json.load(f)
    return []

def save_todos(todos):
    with open(TODO_FILE, "w") as f:
        json.dump(todos, f, indent=2)

def add_todo(todos, text):
    todos.append({"id": len(todos) + 1, "text": text, "done": False})
    save_todos(todos)
    print(f"Added: {text}")

def list_todos(todos):
    if not todos:
        print("No tasks yet.")
        return
    for t in todos:
        status = "[x]" if t["done"] else "[ ]"
        print(f"  {t['id']}. {status} {t['text']}")

def complete_todo(todos, task_id):
    for t in todos:
        if t["id"] == task_id:
            t["done"] = True
            save_todos(todos)
            print(f"Completed: {t['text']}")
            return
    print("Task not found.")

def delete_todo(todos, task_id):
    original = len(todos)
    todos[:] = [t for t in todos if t["id"] != task_id]
    if len(todos) < original:
        save_todos(todos)
        print(f"Deleted task {task_id}.")
    else:
        print("Task not found.")

def main():
    todos = load_todos()
    print("Todo App - Commands: add <text> | list | done <id> | delete <id> | quit")
    while True:
        cmd = input("> ").strip()
        if cmd.startswith("add "):
            add_todo(todos, cmd[4:])
        elif cmd == "list":
            list_todos(todos)
        elif cmd.startswith("done "):
            complete_todo(todos, int(cmd[5:]))
        elif cmd.startswith("delete "):
            delete_todo(todos, int(cmd[7:]))
        elif cmd in ("quit", "exit", "q"):
            break
        else:
            print("Unknown command.")

if __name__ == "__main__":
    main()
```

